import { createHmac } from 'node:crypto';

export interface IntercomWebhookPayload {
  topic: string;
  data: {
    item: {
      type: string;
      id: string;
      url: string;
      subject: string;
      tags: {
        type: string;
        tags: Array<{
          type: string;
          id: string;
          name: string;
          applied_at: number;
          applied_by: {
            type: string;
            id: string;
          };
        }>;
      };
    };
  };
}

export interface ConnectorConfig {
  intercomAccessToken: string;
  zendeskAccessToken: string;
  zendeskSubdomain: string;
  intercomClientSecret?: string;
  webhookRawBody?: string;
  webhookSignature?: string;
  fetch?: typeof fetch;
}

export interface HandleResult {
  zendeskTicketId: number;
  intercomConversationId: string;
}

function verifySignature(
  rawBody: string,
  signature: string,
  clientSecret: string
): void {
  const expected = createHmac('sha1', clientSecret).update(rawBody).digest('hex');
  const provided = signature.replace('sha1=', '');
  if (expected !== provided) {
    throw new Error('Invalid webhook signature');
  }
}

function validatePayload(payload: IntercomWebhookPayload): void {
  if (!payload.topic) throw new Error('Missing required field: topic');
  if (payload.topic !== 'conversation.tag.created') {
    throw new Error(`Unsupported topic: ${payload.topic}`);
  }
  if (!payload.data?.item) throw new Error('Missing required field: data.item');
  const item = payload.data.item;
  if (!item.id) throw new Error('Missing required field: data.item.id');
  if (!item.url) throw new Error('Missing required field: data.item.url');
  if (!item.subject) throw new Error('Missing required field: data.item.subject');
  if (!item.tags?.tags?.length) throw new Error('Missing required field: data.item.tags.tags');
  const refundTag = item.tags.tags.find((t) => t.name === 'refund');
  if (!refundTag) throw new Error("Conversation does not have 'refund' tag");
}

async function fetchIntercomConversation(
  conversationId: string,
  accessToken: string,
  fetchFn: typeof fetch
): Promise<{ id: string; url: string; subject: string }> {
  const url = `https://api.intercom.io/conversations/${conversationId}`;
  const response = await fetchFn(url, {
    method: 'GET',
    headers: {
      Authorization: `Bearer ${accessToken}`,
      Accept: 'application/json',
    },
  });
  if (!response.ok) {
    throw new Error(`Intercom API error: ${response.status} ${response.statusText} for GET ${url}`);
  }
  const data = (await response.json()) as {
    id: string;
    url: string;
    subject: string;
  };
  return { id: data.id, url: data.url, subject: data.subject };
}

async function createZendeskTicket(
  subject: string,
  description: string,
  subdomain: string,
  accessToken: string,
  fetchFn: typeof fetch
): Promise<number> {
  const url = `https://${subdomain}.zendesk.com/api/v2/tickets.json`;
  const body = JSON.stringify({
    ticket: {
      subject,
      comment: { body: description },
    },
  });
  const response = await fetchFn(url, {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${accessToken}`,
      'Content-Type': 'application/json',
    },
    body,
  });
  if (!response.ok) {
    throw new Error(`Zendesk API error: ${response.status} ${response.statusText} for POST ${url}`);
  }
  const data = (await response.json()) as { ticket: { id: number } };
  return data.ticket.id;
}

export async function handle(
  payload: IntercomWebhookPayload,
  config: ConnectorConfig
): Promise<HandleResult> {
  const fetchFn = config.fetch ?? fetch;

  if (config.intercomClientSecret && config.webhookRawBody && config.webhookSignature) {
    verifySignature(config.webhookRawBody, config.webhookSignature, config.intercomClientSecret);
  }

  validatePayload(payload);

  const conversationId = payload.data.item.id;
  const conversation = await fetchIntercomConversation(conversationId, config.intercomAccessToken, fetchFn);

  const subject = `CONV-${conversation.id}: ${conversation.subject}`;
  const description = `Conversation URL: ${conversation.url}\n\nSubject: ${conversation.subject}`;

  const ticketId = await createZendeskTicket(
    subject,
    description,
    config.zendeskSubdomain,
    config.zendeskAccessToken,
    fetchFn
  );

  return { zendeskTicketId: ticketId, intercomConversationId: conversation.id };
}

import { describe, it, expect, vi } from 'vitest';
import { handle, IntercomWebhookPayload, ConnectorConfig } from './connector';
import {
  SOURCE_EXAMPLE,
  TARGET_ENDPOINTS,
  contractFetch,
  fakeFetch,
  jsonResponse,
  RecordedCall,
} from './fixtures';

describe('contract', () => {
  it('handles the documented example payload', async () => {
    const { fetch, calls } = contractFetch();
    const config: ConnectorConfig = {
      intercomAccessToken: 'test-intercom-token',
      zendeskAccessToken: 'test-zendesk-token',
      zendeskSubdomain: 'test-subdomain',
      fetch,
    };
    const result = await handle(SOURCE_EXAMPLE as unknown as IntercomWebhookPayload, config);
    expect(calls.length).toBeGreaterThan(0);
    expect(result).toEqual({ zendeskTicketId: 35436, intercomConversationId: '1911149811' });
  });
});

describe('handle', () => {
  it('happy path: fetches conversation and creates ticket with correct field mapping', async () => {
    const calls: RecordedCall[] = [];
    const fetch = fakeFetch(async (req) => {
      calls.push(req);
      if (req.url === 'https://api.intercom.io/conversations/12345' && req.method === 'GET') {
        return jsonResponse(TARGET_ENDPOINTS[0].response);
      }
      if (req.url === 'https://test-subdomain.zendesk.com/api/v2/tickets.json' && req.method === 'POST') {
        return jsonResponse(TARGET_ENDPOINTS[1].response);
      }
      return jsonResponse({ error: 'not found' }, 404);
    }).fetch;

    const payload: IntercomWebhookPayload = {
      topic: 'conversation.tag.created',
      data: {
        item: {
          type: 'conversation',
          id: '12345',
          url: 'https://app.intercom.com/a/apps/123/inbox/conversations/12345',
          subject: 'Refund request',
          tags: {
            type: 'tag.list',
            tags: [
              {
                type: 'tag',
                id: 'tag_refund',
                name: 'refund',
                applied_at: 1717020000,
                applied_by: { type: 'admin', id: '123' },
              },
            ],
          },
        },
      },
    };

    const config: ConnectorConfig = {
      intercomAccessToken: 'intercom-token',
      zendeskAccessToken: 'zendesk-token',
      zendeskSubdomain: 'test-subdomain',
      fetch,
    };

    const result = await handle(payload, config);

    expect(result).toEqual({ zendeskTicketId: 35436, intercomConversationId: '1911149811' });
    expect(calls).toHaveLength(2);

    const intercomCall = calls[0];
    expect(intercomCall.method).toBe('GET');
    expect(intercomCall.url).toBe('https://api.intercom.io/conversations/12345');
    expect(intercomCall.headers.get('authorization')).toBe('Bearer intercom-token');

    const zendeskCall = calls[1];
    expect(zendeskCall.method).toBe('POST');
    expect(zendeskCall.url).toBe('https://test-subdomain.zendesk.com/api/v2/tickets.json');
    expect(zendeskCall.headers.get('authorization')).toBe('Bearer zendesk-token');
    expect(zendeskCall.json).toEqual({
      ticket: {
        subject: 'CONV-1911149811: Refund request',
        comment: {
          body: 'Conversation URL: https://intercom-survey-app.glitch.me/\n\nSubject: Refund request',
        },
      },
    });
  });

  it('uses Bearer token authentication for both APIs', async () => {
    const calls: RecordedCall[] = [];
    const fetch = fakeFetch(async (req) => {
      calls.push(req);
      if (req.url === 'https://api.intercom.io/conversations/12345') {
        return jsonResponse(TARGET_ENDPOINTS[0].response);
      }
      if (req.url === 'https://mysub.zendesk.com/api/v2/tickets.json') {
        return jsonResponse(TARGET_ENDPOINTS[1].response);
      }
      return jsonResponse({}, 404);
    }).fetch;

    const payload: IntercomWebhookPayload = {
      topic: 'conversation.tag.created',
      data: {
        item: {
          type: 'conversation',
          id: '12345',
          url: 'https://app.intercom.com/conversations/12345',
          subject: 'Test',
          tags: { type: 'tag.list', tags: [{ type: 'tag', id: '1', name: 'refund', applied_at: 1, applied_by: { type: 'admin', id: '1' } }] },
        },
      },
    };

    await handle(payload, {
      intercomAccessToken: 'intercom-auth',
      zendeskAccessToken: 'zendesk-auth',
      zendeskSubdomain: 'mysub',
      fetch,
    });

    expect(calls[0].headers.get('authorization')).toBe('Bearer intercom-auth');
    expect(calls[1].headers.get('authorization')).toBe('Bearer zendesk-auth');
  });

  it('maps conversation.id to subject prefix and conversation.url to description', async () => {
    const calls: RecordedCall[] = [];
    const fetch = fakeFetch(async (req) => {
      calls.push(req);
      if (req.method === 'GET') return jsonResponse(TARGET_ENDPOINTS[0].response);
      if (req.method === 'POST') return jsonResponse(TARGET_ENDPOINTS[1].response);
      return jsonResponse({}, 404);
    }).fetch;

    const payload: IntercomWebhookPayload = {
      topic: 'conversation.tag.created',
      data: {
        item: {
          type: 'conversation',
          id: '999',
          url: 'https://intercom.example.com/conv/999',
          subject: 'Custom subject',
          tags: { type: 'tag.list', tags: [{ type: 'tag', id: '1', name: 'refund', applied_at: 1, applied_by: { type: 'admin', id: '1' } }] },
        },
      },
    };

    await handle(payload, {
      intercomAccessToken: 't1',
      zendeskAccessToken: 't2',
      zendeskSubdomain: 'sub',
      fetch,
    });

    const postCall = calls[1];
    expect(postCall.json).toEqual({
      ticket: {
        subject: 'CONV-1911149811: Refund request',
        comment: { body: 'Conversation URL: https://intercom-survey-app.glitch.me/\n\nSubject: Refund request' },
      },
    });
  });

  it('throws descriptive error when required field data.item.id is missing', async () => {
    const fetch = fakeFetch(() => jsonResponse({}, 200)).fetch;
    const payload = {
      topic: 'conversation.tag.created',
      data: { item: { type: 'conversation', url: 'x', subject: 's', tags: { type: 'tag.list', tags: [{ type: 'tag', id: '1', name: 'refund', applied_at: 1, applied_by: { type: 'admin', id: '1' } }] } } },
    } as unknown as IntercomWebhookPayload;

    await expect(handle(payload, { intercomAccessToken: 'a', zendeskAccessToken: 'b', zendeskSubdomain: 'c', fetch })).rejects.toThrow('Missing required field: data.item.id');
  });

  it('throws descriptive error when refund tag is missing', async () => {
    const fetch = fakeFetch(() => jsonResponse({}, 200)).fetch;
    const payload: IntercomWebhookPayload = {
      topic: 'conversation.tag.created',
      data: {
        item: {
          type: 'conversation',
          id: '1',
          url: 'x',
          subject: 's',
          tags: { type: 'tag.list', tags: [{ type: 'tag', id: '1', name: 'other', applied_at: 1, applied_by: { type: 'admin', id: '1' } }] },
        },
      },
    };

    await expect(handle(payload, { intercomAccessToken: 'a', zendeskAccessToken: 'b', zendeskSubdomain: 'c', fetch })).rejects.toThrow("Conversation does not have 'refund' tag");
  });

  it('throws error with status and endpoint on non-2xx Intercom response', async () => {
    const fetch = fakeFetch(() => jsonResponse({ error: 'not found' }, 404)).fetch;
    const payload: IntercomWebhookPayload = {
      topic: 'conversation.tag.created',
      data: {
        item: {
          type: 'conversation',
          id: '12345',
          url: 'x',
          subject: 's',
          tags: { type: 'tag.list', tags: [{ type: 'tag', id: '1', name: 'refund', applied_at: 1, applied_by: { type: 'admin', id: '1' } }] },
        },
      },
    };

    await expect(handle(payload, { intercomAccessToken: 'a', zendeskAccessToken: 'b', zendeskSubdomain: 'c', fetch })).rejects.toThrow('Intercom API error: 404 Not Found for GET https://api.intercom.io/conversations/12345');
  });

  it('throws error with status and endpoint on non-2xx Zendesk response', async () => {
    const calls: RecordedCall[] = [];
    const fetch = fakeFetch(async (req) => {
      calls.push(req);
      if (req.method === 'GET') return jsonResponse(TARGET_ENDPOINTS[0].response);
      return jsonResponse({ error: 'unauthorized' }, 401);
    }).fetch;

    const payload: IntercomWebhookPayload = {
      topic: 'conversation.tag.created',
      data: {
        item: {
          type: 'conversation',
          id: '12345',
          url: 'x',
          subject: 's',
          tags: { type: 'tag.list', tags: [{ type: 'tag', id: '1', name: 'refund', applied_at: 1, applied_by: { type: 'admin', id: '1' } }] },
        },
      },
    };

    await expect(handle(payload, { intercomAccessToken: 'a', zendeskAccessToken: 'b', zendeskSubdomain: 'c', fetch })).rejects.toThrow('Zendesk API error: 401 Unauthorized for POST https://c.zendesk.com/api/v2/tickets.json');
  });

  it('verifies webhook signature when secret and raw body provided', async () => {
    const calls: RecordedCall[] = [];
    const fetch = fakeFetch(async (req) => {
      calls.push(req);
      if (req.method === 'GET') return jsonResponse(TARGET_ENDPOINTS[0].response);
      if (req.method === 'POST') return jsonResponse(TARGET_ENDPOINTS[1].response);
      return jsonResponse({}, 404);
    }).fetch;

    const rawBody = JSON.stringify(SOURCE_EXAMPLE);
    const crypto = await import('node:crypto');
    const signature = 'sha1=' + crypto.createHmac('sha1', 'secret').update(rawBody).digest('hex');

    const payload: IntercomWebhookPayload = SOURCE_EXAMPLE as unknown as IntercomWebhookPayload;

    await handle(payload, {
      intercomAccessToken: 'a',
      zendeskAccessToken: 'b',
      zendeskSubdomain: 'c',
      intercomClientSecret: 'secret',
      webhookRawBody: rawBody,
      webhookSignature: signature,
      fetch,
    });

    expect(calls.length).toBe(2);
  });

  it('throws on invalid signature', async () => {
    const fetch = fakeFetch(() => jsonResponse({}, 200)).fetch;
    const payload: IntercomWebhookPayload = SOURCE_EXAMPLE as unknown as IntercomWebhookPayload;

    await expect(handle(payload, {
      intercomAccessToken: 'a',
      zendeskAccessToken: 'b',
      zendeskSubdomain: 'c',
      intercomClientSecret: 'secret',
      webhookRawBody: '{}',
      webhookSignature: 'sha1=invalid',
      fetch,
    })).rejects.toThrow('Invalid webhook signature');
  });
});

